/*
 * VelaWear - SF32LB52 on-chip audio hardware test.
 *
 * This finite diagnostic exercises the board's internal AUDCODEC directly.
 * The current NuttX port has no /dev/audio registration yet.
 */

#include <nuttx/config.h>

#ifndef SOC_BF0_HCPU
#  define SOC_BF0_HCPU 1
#endif
#ifndef SF32LB52X
#  define SF32LB52X 1
#endif

#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>

#include "bf0_hal.h"
#include "audio_hw_test.h"

#define AUDIO_TEST_RATE       16000
#define AUDIO_TEST_SECONDS    2
#define AUDIO_TEST_SAMPLES    (AUDIO_TEST_RATE * AUDIO_TEST_SECONDS)
#define AUDIO_FIFO_WATERMARK  8
#define AUDIO_PA_PIN          42

static const int16_t g_tone[32] =
{
   0,  6393, 12539, 18204, 23170, 27245, 30273, 32137,
   32767, 32137, 30273, 27245, 23170, 18204, 12539, 6393,
   0, -6393, -12539, -18204, -23170, -27245, -30273, -32137,
  -32768,-32137,-30273,-27245,-23170,-18204,-12539,-6393
};

static const AUDCODE_DAC_CLK_CONFIG_TYPE g_dac_clock =
{
  AUDIO_TEST_RATE, 0, 1, 4, 0x14d, 0, 5, 4, 2, 20, 20, 0
};

static const AUDCODE_ADC_CLK_CONFIG_TYPE g_adc_clock =
{
  AUDIO_TEST_RATE, 0, 10, 1, 0, 0, 5, 2
};

static void audio_pa_set(bool enabled)
{
  GPIO_InitTypeDef init;

  memset(&init, 0, sizeof(init));
  init.Pin = AUDIO_PA_PIN;
  init.Mode = GPIO_MODE_OUTPUT;
  init.Pull = GPIO_PULLDOWN;
  HAL_GPIO_Init((GPIO_TypeDef *)hwp_gpio1, &init);
  HAL_GPIO_WritePin((GPIO_TypeDef *)hwp_gpio1, AUDIO_PA_PIN,
                    enabled ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

static uint32_t audio_dac_fifo_count(void)
{
  return (hwp_audcodec->APB_STAT &
          AUDCODEC_APB_STAT_DAC_CH0_FIFO_CNT_Msk) >>
         AUDCODEC_APB_STAT_DAC_CH0_FIFO_CNT_Pos;
}

static uint32_t audio_adc_fifo_count(void)
{
  return (hwp_audcodec->APB_STAT &
          AUDCODEC_APB_STAT_ADC_CH0_FIFO_CNT_Msk) >>
         AUDCODEC_APB_STAT_ADC_CH0_FIFO_CNT_Pos;
}

static void audio_dac_stop(AUDCODEC_HandleTypeDef *codec)
{
  HAL_AUDCODEC_Config_DACPath(codec, 1);
  __HAL_AUDCODEC_DAC_DISABLE(codec);
  HAL_AUDCODEC_Close_Analog_DACPath();
}

static void audio_adc_stop(AUDCODEC_HandleTypeDef *codec)
{
  __HAL_AUDCODEC_ADC_DISABLE(codec);
  HAL_AUDCODEC_Close_Analog_ADCPath();
}

int velawear_audio_hw_test(void)
{
  AUDCODEC_HandleTypeDef codec;
  AUDCODEC_DACCfgTypeDef dac_cfg;
  AUDCODEC_ADCCfgTypeDef adc_cfg;
  int ret = HAL_OK;
  int i;

  memset(&codec, 0, sizeof(codec));
  codec.Instance = hwp_audcodec;
  codec.Init.dac_cfg.opmode = 1;
  codec.Init.adc_cfg.opmode = 1;

  syslog(LOG_INFO, "[AudioTest] SF32LB52 AUDCODEC test begin\n");

  HAL_PMU_EnableAudio(1);
  HAL_RCC_EnableModule(RCC_MOD_AUDCODEC);
  ret = HAL_AUDCODEC_Init(&codec);
  if (ret != HAL_OK)
    {
      syslog(LOG_ERR, "[AudioTest] HAL_AUDCODEC_Init failed: %d\n", ret);
      HAL_PMU_EnableAudio(0);
      return -1;
    }

  dac_cfg.opmode = 1;
  dac_cfg.dac_clk = (AUDCODE_DAC_CLK_CONFIG_TYPE *)&g_dac_clock;
  ret = HAL_AUDCODEC_Config_TChanel(&codec, 0, &dac_cfg);
  if (ret != HAL_OK)
    {
      syslog(LOG_ERR, "[AudioTest] DAC channel config failed: %d\n", ret);
      goto cleanup;
    }

  __HAL_AUDCODEC_DAC_ENABLE(&codec);
  HAL_AUDCODEC_Config_DACPath(&codec, 1);
  HAL_TURN_ON_PLL();
  ret = HAL_AUDCODEC_Config_Analog_DACPath(
          (AUDCODE_DAC_CLK_CONFIG_TYPE *)&g_dac_clock);
  if (ret != HAL_OK)
    {
      syslog(LOG_ERR, "[AudioTest] analog DAC path failed: %d\n", ret);
      goto cleanup;
    }

  audio_pa_set(true);
  syslog(LOG_INFO, "[AudioTest] SPEAKER: 1 kHz tone for %d seconds\n",
         AUDIO_TEST_SECONDS);

  {
    uint32_t queued = 0;
    for (i = 0; i < AUDIO_TEST_SAMPLES; i++)
      {
        uint32_t guard = 0;
        while (audio_dac_fifo_count() >= AUDIO_FIFO_WATERMARK &&
               guard++ < 10)
          {
            HAL_Delay_us(20);
          }
        if (audio_dac_fifo_count() < AUDIO_FIFO_WATERMARK)
          {
            hwp_audcodec->DAC_CH0_ENTRY = (uint16_t)g_tone[i & 31];
            queued++;
          }
      }
    syslog(LOG_INFO, "[AudioTest] SPEAKER: queued=%lu/%d\n",
           (unsigned long)queued, AUDIO_TEST_SAMPLES);
  }

  audio_pa_set(false);
  audio_dac_stop(&codec);
  syslog(LOG_INFO, "[AudioTest] SPEAKER: tone feed complete\n");

  adc_cfg.opmode = 1;
  adc_cfg.adc_clk = (AUDCODE_ADC_CLK_CONFIG_TYPE *)&g_adc_clock;
  ret = HAL_AUDCODEC_Config_RChanel(&codec, 0, &adc_cfg);
  if (ret != HAL_OK)
    {
      syslog(LOG_ERR, "[AudioTest] ADC channel config failed: %d\n", ret);
      goto cleanup;
    }

  HAL_AUDCODEC_Config_Analog_ADCPath((AUDCODE_ADC_CLK_CONFIG_TYPE *)&g_adc_clock);
  __HAL_AUDCODEC_ADC_ENABLE(&codec);
  {
    int32_t min_sample = INT32_MAX;
    int32_t max_sample = INT32_MIN;
    uint64_t sum_abs = 0;
    uint32_t samples = 0;
    uint32_t idle_loops = 0;

    syslog(LOG_INFO, "[AudioTest] MICROPHONE: sampling for %d seconds\n",
           AUDIO_TEST_SECONDS);

    while (samples < AUDIO_TEST_SAMPLES && idle_loops < 20000)
      {
        if (audio_adc_fifo_count() == 0)
          {
            HAL_Delay_us(100);
            idle_loops++;
            continue;
          }

        {
          int32_t sample = (int16_t)(hwp_audcodec->ADC_CH0_ENTRY & 0xffff);
          if (sample < min_sample)
            {
              min_sample = sample;
            }
          if (sample > max_sample)
            {
              max_sample = sample;
            }
          sum_abs += (uint32_t)(sample < 0 ? -sample : sample);
          samples++;
        }
      }

    if (samples == 0)
      {
        syslog(LOG_ERR, "[AudioTest] MICROPHONE: no ADC samples\n");
      }
    else
      {
        syslog(LOG_INFO,
               "[AudioTest] MICROPHONE: samples=%lu min=%ld max=%ld avg_abs=%lu\n",
               (unsigned long)samples, (long)min_sample, (long)max_sample,
               (unsigned long)(sum_abs / samples));
      }
  }

  audio_adc_stop(&codec);

cleanup:
  audio_pa_set(false);
  HAL_AUDCODEC_DeInit(&codec);
  HAL_TURN_OFF_PLL();
  HAL_PMU_EnableAudio(0);
  syslog(LOG_INFO, "[AudioTest] complete\n");
  return ret == HAL_OK ? 0 : -1;
}

## Subagent dispatch requires multi-agent support

Add to your Codex config (`~/.codex/config.toml`):

```toml
[features]
multi_agent = true
```

This enables `spawn_agent`, `wait_agent`, and `close_agent` for skills like `dispatching-parallel-agents` and `subagent-driven-development`. When using subagent-driven-development, close reviewer subagents when their review returns. Keep each implementer subagent open until its task's review passes — the fix loop resumes the implementer — then close it. If your harness cannot send another message to a spawned agent, dispatch each fix round as a fresh implementer carrying the brief, the report file, and the findings.

## Environment Detection

Skills that create worktrees or finish branches should detect their
environment with read-only git commands before proceeding:

```bash
GIT_DIR=$(cd "$(git rev-parse --git-dir)" 2>/dev/null && pwd -P)
GIT_COMMON=$(cd "$(git rev-parse --git-common-dir)" 2>/dev/null && pwd -P)
BRANCH=$(git branch --show-current)
```

- `GIT_DIR != GIT_COMMON` → already in a linked worktree (skip creation)
- `BRANCH` empty → detached HEAD (cannot branch/push/PR from sandbox)

See `using-git-worktrees` Step 0 and `finishing-a-development-branch`
Step 1 for how each skill uses these signals.

## Codex App Finishing

When the sandbox blocks branch/push operations (detached HEAD in an
externally managed worktree), the agent commits all work and informs
the user to use the App's native controls:

- **"Create branch"** — names the branch, then commit/push/PR via App UI
- **"Hand off to local"** — transfers work to the user's local checkout

The agent can still run tests, stage files, and output suggested branch
names, commit messages, and PR descriptions for the user to copy.

# 串口监视 Skill 用法

这个 skill 自带了一个可执行脚本 [scripts/serial_monitor.py](../scripts/serial_monitor.py)，适合在需要重复抓串口日志、验证启动行为或捕获早期启动信息时直接调用。

## 能力概览

- 自动列出并识别常见串口设备
- 自动选择最可能的串口
- 定长抓取、等待关键字符串、交互式持续监视
- 保存日志到文件，并可为每行追加时间戳
- 对日志做基础状态分析，快速区分正常/警告/错误
- 支持“先监听再复位”，降低启动日志丢失概率
- 可选通过 OpenOCD 自动复位目标板

## 基础用法

```bash
# 列出串口
python3 skills/serial-monitor/scripts/serial_monitor.py --list

# 自动检测串口并读取 5 秒
python3 skills/serial-monitor/scripts/serial_monitor.py --auto --duration 5

# 指定串口和波特率
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --port /dev/ttyACM0 \
  --baud 115200 \
  --duration 3
```

## 常见模式

### 1. 等待关键字符串

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --port /dev/ttyACM0 \
  --wait "System Start"
```

适合验证系统是否完成启动，或是否输出某段断言/错误文本。

### 2. 交互式持续监视

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --port COM7 \
  --monitor \
  --timestamp
```

- 持续显示串口输出
- 使用 `Ctrl+C` 退出
- 推荐在联调阶段开启 `--timestamp`

### 3. 保存日志

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto \
  --duration 30 \
  --save logs/run.log
```

日志文件会自动创建父目录，并逐行追加写入。

### 4. 先监听，再等待复位

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto \
  --wait-reset \
  --duration 5 \
  --save logs/startup.log
```

推荐用于容易丢失早期启动日志的场景。流程为：

1. 先打开串口并开始监听
2. 提示用户复位目标板
3. 检测到新的串口数据后立即开始记录
4. 输出分析结果并保存启动日志

### 5. 使用 OpenOCD 自动复位

如果已经明确 OpenOCD 配置，可以把复位动作也交给脚本：

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto \
  --wait-reset \
  --auto-reset \
  --interface stlink \
  --openocd-target target/stm32f4x.cfg \
  --duration 5
```

也可以直接传入完整板级配置：

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --port /dev/ttyUSB0 \
  --wait-reset \
  --auto-reset \
  --openocd-config board/st_nucleo_f4.cfg \
  --duration 5
```

注意：

- `--auto-reset` 必须与 `--wait-reset` 一起使用
- 至少提供 `--openocd-config` 或 `--openocd-target`
- 如果不显式指定 `--interface`，脚本会尝试探测 `stlink`、`cmsis-dap`、`jlink`

## 参数说明

| 参数 | 说明 |
| --- | --- |
| `--list` | 列出所有可见串口 |
| `--auto` | 自动选择最可能的串口 |
| `--port` | 显式指定串口 |
| `--baud` | 波特率，默认 `115200` |
| `--duration` | 读取时长（秒） |
| `--clear` | 读取前清空缓冲区 |
| `--wait` | 等待指定字符串出现后结束 |
| `--monitor` | 持续监视，直到 `Ctrl+C` |
| `--save` | 将日志保存到文件 |
| `--timestamp` | 为每行输出加时间戳 |
| `-v`, `--verbose` | 打印更详细的统计信息 |
| `--keep` | 保留已有缓冲区内容 |
| `--wait-reset` | 先监听，再等待目标复位 |
| `--auto-reset` | 在等待复位模式下通过 OpenOCD 自动复位 |
| `--interface` | 调试接口：`stlink`、`cmsis-dap`、`daplink`、`jlink` |
| `--no-detect` | 禁止自动探测调试接口 |
| `--openocd-config` | 额外传入 OpenOCD `-f` 配置，可重复 |
| `--openocd-target` | 目标或板级 OpenOCD 配置，可重复 |
| `--openocd-command` | 自动复位时执行的 OpenOCD 命令 |

## 返回码

- `0`：串口会话成功，或虽未识别明确健康信号但没有发现硬错误
- `1`：参数非法、依赖缺失、串口无法打开、检测到错误相关日志，或用户中断

## AI 使用场景

### 场景 1：验证系统启动

```bash
# 烧录后等待启动信息
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto --wait "System Start"
# 输出: ✅ 检测到关键字符串: System Start
```

### 场景 2：检测运行错误

```bash
# 读取 10 秒，检查是否有错误
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto --duration 10 -v
# 如果有错误会显示:
# ❌ 检测到 1 条错误相关日志
# ❌ 错误样例:
#   [ERROR] I2C timeout
```

### 场景 3：一键复位并捕获完整启动日志

```bash
# 自动复位（最简单，需要 OpenOCD + 调试器）
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto --wait-reset --auto-reset \
  --interface stlink --openocd-target target/stm32f4x.cfg \
  --duration 5 -v
```

### 场景 4：保存测试日志供后续分析

```bash
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto --duration 60 --save test_log.txt --timestamp
```

## 推荐工作流

### 标准工作流（芯片已在运行）

```bash
# 1. 等待启动完成
python3 skills/serial-monitor/scripts/serial_monitor.py --auto --wait "System Start"

# 2. 检查运行状态
python3 skills/serial-monitor/scripts/serial_monitor.py --auto --duration 3 -v

# 3. 持续监控
python3 skills/serial-monitor/scripts/serial_monitor.py --auto --monitor --timestamp
```

### 捕获完整启动日志

```bash
# 方法 1：自动复位（推荐）
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto --wait-reset --auto-reset \
  --interface stlink --openocd-target target/stm32f4x.cfg \
  --duration 5 --save startup.log

# 方法 2：手动复位
python3 skills/serial-monitor/scripts/serial_monitor.py \
  --auto --wait-reset --duration 5 --save startup.log
# 看到提示后，在另一个终端烧录或按复位键

# 方法 3：读取缓冲区历史数据
python3 skills/serial-monitor/scripts/serial_monitor.py --auto --keep
```

### 场景选择参考

| 场景 | 推荐参数 |
|------|---------|
| 一键复位+监控 | `--auto --wait-reset --auto-reset --interface ... --openocd-target ...` |
| 烧录后查看日志 | `--auto --wait-reset` |
| 芯片已在运行 | `--auto --keep` |
| 长时间监控 | `--auto --monitor --timestamp` |
| 保存启动日志 | `--auto --wait-reset --auto-reset --save log.txt` |
| 验证特定功能 | `--auto --wait "OK"` |

## 故障排查

### 提示 PermissionError

串口被其他程序占用。关闭串口助手、IDE 或其他监视工具。

### 自动检测选择了错误的串口

使用 `--list` 查看所有串口，然后用 `--port` 手动指定。

### 看不到输出

1. 检查波特率是否匹配（默认 115200）
2. 检查 TX/RX 是否接反
3. 使用 `--clear` 清空缓冲区
4. 尝试复位开发板

### --wait-reset 模式超时

- 确保在 30 秒内复位芯片或烧录固件
- 检查串口连接是否正确
- 检查芯片是否正常工作

### --auto-reset 失败

1. 确认 OpenOCD 已安装：`openocd --version`
2. 确认调试器已连接且驱动正常
3. 确认 SWD 接线正确（SWDIO→PA13, SWCLK→PA14, GND→GND）
4. 尝试用 `--interface` 手动指定调试器类型

## 依赖安装

```bash
# 基础依赖（必需）
pip install pyserial

# OpenOCD（仅 --auto-reset 功能需要）
# Linux: sudo apt install openocd
# macOS: brew install openocd
# Windows: https://github.com/openocd-org/openocd/releases
```

## 与 Skill 的配合方式

在 `serial-monitor` skill 中，推荐工作流是：

1. 先根据用户输入或 `Project Profile` 决定端口和波特率
2. 选择合适的脚本模式，例如 `--wait`、`--monitor`、`--wait-reset`
3. 将脚本分析结果整理成简洁摘要，而不是原样粘贴整段日志
4. 若日志显示 Fault、断言、死循环或启动异常，交给 `debug-gdb-openocd`

# 问题分类表

按现象分类，每个现象列出可能原因和验证方法。

---

## ADC 相关

### 现象：ADC 值不动（一直读到同一个值）
| 可能原因 | 验证方法 | 寄存器 |
|---------|---------|--------|
| DMA 未启动 | 读 DMA Stream CR 寄存器 | DMA_SxCR.EN = 1 |
| TIM 未触发 | 读 TIM CR1 寄存器 | TIM_CR1.CEN = 1 |
| ADC 未使能 | 读 ADC CR2 寄存器 | ADC_CR2.ADON = 1 |
| ADC 未开始转换 | 读 ADC CR2 | ADC_CR2.SWSTART = 1 |
| 时钟未开 | 读 RCC AHB1ENR | 对应位 = 1 |

### 现象：ADC 值全为 0
| 可能原因 | 验证方法 | 寄存器 |
|---------|---------|--------|
| 引脚配置错误 | 检查 GPIO 模式 | GPIO_MODER = 模拟输入 |
| ADC 通道选错 | 检查 ADC SQR | ADC_SQRx 中的通道号 |
| DMA 传输地址错 | 检查 DMA 目标地址 | DMA_SxPAR, DMA_SxM0AR |
| 采样时间太短 | 检查 ADC SMPR | ADC_SMPRx |

### 现象：ADC 值范围很小（如只有 100-200）
| 可能原因 | 验证方法 | 寄存器 |
|---------|---------|--------|
| 采样时间太短 | 检查采样周期 | ADC_SMPRx（高阻源需要更长） |
| 参考电压不对 | 测量 VREF 引脚 | 万用表 |
| 信号源阻抗太高 | 测量信号源 | 万用表 |

### 现象：ADC 值有噪声
