{
    uint32_t rough_vol, fine_vol;

    /* Check the AUDCODEC handle allocation */
    if (hacodec == NULL)
    {
        return HAL_ERROR;
    }

    if ((channel < 0) || (channel > 1))
    {
        return HAL_ERROR;
    }

    if ((volume < -60) || (volume > 30))
    {
        return HAL_ERROR;
    }

    rough_vol = (volume + 60) / 6;
    fine_vol  = ((volume + 60) % 6) << 1;

    if (channel == 0)
