    if (hacodec->State[0] == HAL_AUDCODEC_STATE_RESET)
    {
        /* Allocate lock resource and initialize it */
        hacodec->Lock = HAL_UNLOCKED;

        /* Init the low level hardware : GPIO, CLOCK, CORTEX...etc */
        HAL_AUDCODEC_MspInit(hacodec);
