    for (i = 0; i < HAL_AUDCODEC_INSTANC_CNT; i++)
        if (hacodec->hdma[i] != NULL)
            hacodec->hdma[i]->Parent = (void *)hacodec;

    for (i = HAL_AUDCODEC_DAC_CH0; i < HAL_AUDCODEC_ADC_CH0; i++)
