        if (hacodec->hdma[i] != NULL)
            HAL_AUDCODEC_DMA_Init(hacodec->hdma[i], 1);
    }
    for (i = HAL_AUDCODEC_ADC_CH0; i < HAL_AUDCODEC_INSTANC_CNT; i++)
    {
        if (hacodec->hdma[i] != NULL)
            HAL_AUDCODEC_DMA_Init(hacodec->hdma[i], 0);
