186	def fragment_data(data: bytes, frag_payload_max: int = FRAG_PAYLOAD_MAX_BLE42) -> list:
187	    """
188	    Fragment data into BLE-sized chunks with fragment headers.
189	
190	    Returns a list of bytes objects, each ready to send via BLE.
191	    """
192	    total = (len(data) + frag_payload_max - 1) // frag_payload_max
193	    if total > 255:
194	        raise ValueError(
195	            f"Data too large for fragmentation: {len(data)} bytes "
196	            f"({total} fragments, max 255)"
197	        )
198	
199	    fragments = []
200	    # Use a simple incrementing fragment ID (wraps at 256)
201	    frag_id = int(time.monotonic() * 1000) & 0xFF
202	
203	    offset = 0
204	    for index in range(total):
205	        remaining = len(data) - offset
206	        chunk_len = min(remaining, frag_payload_max)
207	        header = struct.pack("BBBB", frag_id, total, index, chunk_len)
208	        fragments.append(header + data[offset : offset + chunk_len])
209	        offset += chunk_len
210	
211	    log.info(
212	        "Fragmented %d bytes into %d fragments (id=%d)",
213	        len(data),
214	        total,
215	        frag_id,
216	    )
217	    return fragments
