   223	  if (ret < 0)
   224	    {
   225	      syslog(LOG_WARNING, "[VelaWear] Audio sensor init failed: %d\n", ret);
   226	      /* Non-fatal: continue without audio */
   227	    }
   228	
   229	  /* Initialize LLM client */
   230	
   231	  ret = velawear_llm_init(&agent->llm);
   232	  if (ret < 0)
   233	    {
   234	      syslog(LOG_WARNING, "[VelaWear] LLM init failed: %d\n", ret);
   235	      /* Non-fatal: continue without LLM */
   236	    }
   237	
   238	  ret = event_manager_register_handler(&agent->events,
   239	                                       VELAWEAR_EVENT_NONE,
   240	                                       velawear_event_handler,
   241	                                       agent,
   242	                                       VELAWEAR_PRIORITY_NORMAL);
   243	  if (ret < 0)
   244	    {
   245	      syslog(LOG_ERR, "[VelaWear] Event handler registration failed: %d\n",
   246	             ret);
   247	      return ret;
   248	    }
   249	
   250	  ret = action_manager_register_handler(&agent->actions,
   251	                                        VELAWEAR_ACTION_LOG,
   252	                                        velawear_log_action_handler,
   253	                                        agent);
   254	  if (ret < 0)
   255	    {
   256	      syslog(LOG_ERR, "[VelaWear] Action handler registration failed: %d\n",
   257	             ret);
   258	      return ret;
   259	    }
   260	
   261	  return OK;
   262	}
   263	
   264	static int velawear_start(velawear_agent_t *agent)
   265	{
   266	  int ret;
   267	
   268	  /* Start event manager thread */
   269	
   270	  ret = event_manager_start(&agent->events);
   271	  if (ret < 0)
   272	    {
   273	      syslog(LOG_ERR, "[VelaWear] Event manager start failed: %d\n", ret);
   274	      return ret;
   275	    }
   276	
   277	  /* Start action manager thread. */
   278	
   279	  ret = action_manager_start(&agent->actions);
   280	  if (ret < 0)
   281	    {
   282	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
   283	      return ret;
   284	    }
   285	
   286	  /* Decision rules are evaluated synchronously for each event. */
   287	
   288	  /* Mark agent as running */
   289	
   290	  agent->running = true;
   291	
   292	  return OK;
   293	}
   294	
   295	static void velawear_cleanup(velawear_agent_t *agent)
   296	{
   297	  /* Stop subsystems in reverse order */
   298	
   299	  agent->running = false;
   300	
   301	  velawear_llm_cleanup(&agent->llm);
   302	  audio_sensor_cleanup(&agent->audio);
   303	  imu_sensor_cleanup(&agent->imu);
   304	  action_manager_cleanup(&agent->actions);
   305	  event_manager_cleanup(&agent->events);
   306	  decision_engine_cleanup(&agent->engine);
   307	  display_manager_cleanup(&agent->display);
   308	  state_manager_cleanup(&agent->state_mgr);
   309	  velawear_config_cleanup(&agent->config);
   310	}
   311	
   312	static void velawear_signal_handler(int signo)
   313	{
   314	  syslog(LOG_INFO, "[VelaWear] Received signal %d, shutting down\n", signo);
   315	  g_agent.running = false;
   316	}
   317	
   318	static int velawear_event_handler(velawear_event_t *event, void *context)
   319	{
   320	  velawear_agent_t *agent = (velawear_agent_t *)context;
   321	  velawear_state_t state;
   322	
   323	  if (event->type == VELAWEAR_EVENT_IMU_DATA)
   324	    {
   325	      motion_state_t motion = imu_sensor_get_motion_state(&agent->imu);
   326	      state_manager_update_motion(&agent->state_mgr,
   327	                                  motion.is_moving,
   328	                                  motion.is_running);
   329	    }
   330	
   331	  state = state_manager_get_state(&agent->state_mgr);
   332	  agent->state = state;
   333	  decision_engine_evaluate(&agent->engine, &state, event);
   334	  return VELAWEAR_OK;
   335	}
   336	
   337	static int velawear_log_action_handler(velawear_action_t *action,
   338	                                       void *context)
   339	{
   340	  if (action)
   341	    {
   342	      syslog(LOG_INFO, "[VelaWear] action %d executed\n", action->type);
   343	    }
   344	
   345	  return VELAWEAR_OK;
   346	}
