     1	/*
     2	 * VelaWear Agent - Main Entry Point
     3	 *
     4	 * This is the main entry point for the VelaWear Agent application.
     5	 * It initializes all subsystems and starts the main event loop.
     6	 *
     7	 * Author: pjjuihj
     8	 * Team: 329 - dela
     9	 */
    10	
    11	#include <nuttx/config.h>
    12	#include <stdio.h>
    13	#include <stdlib.h>
    14	#include <string.h>
    15	#include <unistd.h>
    16	#include <errno.h>
    17	#include <signal.h>
    18	#include <syslog.h>
    19	
    20	#include "velawear.h"
    21	#include "audio_hw_test.h"
    22	
    23	/* Global agent instance */
    24	
    25	static velawear_agent_t g_agent;
    26	
    27	/* Forward declarations */
    28	
    29	static int velawear_init(velawear_agent_t *agent);
    30	static int velawear_start(velawear_agent_t *agent);
    31	static void velawear_cleanup(velawear_agent_t *agent);
    32	static void velawear_signal_handler(int signo);
    33	static int velawear_event_handler(velawear_event_t *event, void *context);
    34	static int velawear_log_action_handler(velawear_action_t *action,
    35	                                       void *context);
    36	
    37	/****************************************************************************
    38	 * Public Functions
    39	 ****************************************************************************/
    40	
    41	int main(int argc, char *argv[])
    42	{
    43	  int ret;
    44	
    45	  if (argc > 1 && strcmp(argv[1], "audio") == 0)
    46	    {
    47	      return velawear_audio_hw_test();
    48	    }
    49	
    50	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
    51	  if (argc > 1 && strcmp(argv[1], "mic") == 0)
    52	    {
    53	      return velawear_mic_hw_test();
    54	    }
    55	
    56	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
    57	
    58	  /* Initialize agent structure */
    59	
    60	  memset(&g_agent, 0, sizeof(velawear_agent_t));
    61	  g_agent.running = false;
    62	  g_agent.power_mode = VELAWEAR_POWER_IDLE;
    63	
    64	  /* Set up signal handler */
    65	
    66	  signal(SIGTERM, velawear_signal_handler);
    67	  signal(SIGINT, velawear_signal_handler);
    68	
    69	  /* Initialize subsystems */
    70	
    71	  ret = velawear_init(&g_agent);
    72	  if (ret < 0)
    73	    {
    74	      syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
    75	      return EXIT_FAILURE;
    76	    }
    77	
    78	  /* Start the agent */
    79	
    80	  ret = velawear_start(&g_agent);
    81	  if (ret < 0)
    82	    {
    83	      syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
    84	      velawear_cleanup(&g_agent);
    85	      return EXIT_FAILURE;
    86	    }
    87	
    88	  syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
    89	
    90	  /* Main loop: sample the board IMU and feed the event pipeline. */
    91	
    92	  bool fall_reported = false;
    93	  while (g_agent.running)
    94	    {
    95	      int period_us = 20000;
    96	
    97	      if (g_agent.imu.initialized)
    98	        {
    99	          imu_data_t sample;
   100	          motion_state_t motion;
   101	          velawear_event_t event;
   102	          int sample_ret;
   103	
   104	          sample_ret = imu_sensor_read(&g_agent.imu, &sample);
   105	          if (sample_ret == VELAWEAR_OK)
   106	            {
   107	              memset(&event, 0, sizeof(event));
   108	              event.type = VELAWEAR_EVENT_IMU_DATA;
   109	              event.priority = VELAWEAR_PRIORITY_NORMAL;
   110	              event.timestamp = sample.timestamp;
   111	              event.data.imu.x = sample.accel_x;
   112	              event.data.imu.y = sample.accel_y;
   113	              event.data.imu.z = sample.accel_z;
   114	              event_manager_push(&g_agent.events, &event);
   115	
   116	              motion = imu_sensor_get_motion_state(&g_agent.imu);
   117	              if (motion.fall_detected && !fall_reported)
   118	                {
   119	                  event.type = VELAWEAR_EVENT_FALL;
   120	                  event.priority = VELAWEAR_PRIORITY_CRITICAL;
   121	                  event_manager_push(&g_agent.events, &event);
   122	                  fall_reported = true;
   123	                }
   124	              else if (!motion.fall_detected)
   125	                {
   126	                  fall_reported = false;
   127	                }
   128	            }
   129	
   130	          if (g_agent.config.imu_sample_rate_hz > 0)
   131	            {
   132	              period_us = 1000000 / g_agent.config.imu_sample_rate_hz;
   133	              if (period_us < 1000)
   134	                {
   135	                  period_us = 1000;
   136	                }
   137	            }
   138	        }
   139	
   140	      /* LVGL initialization and timer handling stay on this task. */
   141	
   142	      display_manager_tick(&g_agent.display);
   143	      usleep(period_us);
   144	    }
   145	
   146	  /* Cleanup */
   147	
   148	  velawear_cleanup(&g_agent);
   149	  syslog(LOG_INFO, "[VelaWear] Agent stopped\n");
   150	
   151	  return EXIT_SUCCESS;
   152	}
