   154	/****************************************************************************
   155	 * Private Functions
   156	 ****************************************************************************/
   157	
   158	static int velawear_init(velawear_agent_t *agent)
   159	{
   160	  int ret;
   161	
   162	  /* Initialize configuration */
   163	
   164	  ret = velawear_config_init(&agent->config);
   165	  if (ret < 0)
   166	    {
   167	      syslog(LOG_ERR, "[VelaWear] Config init failed: %d\n", ret);
   168	      return ret;
   169	    }
   170	
   171	  /* Initialize event manager */
   172	
   173	  ret = event_manager_init(&agent->events);
   174	  if (ret < 0)
   175	    {
   176	      syslog(LOG_ERR, "[VelaWear] Event manager init failed: %d\n", ret);
   177	      return ret;
   178	    }
   179	
   180	  /* Initialize state manager */
   181	
   182	  ret = state_manager_init(&agent->state_mgr);
   183	  if (ret < 0)
   184	    {
   185	      syslog(LOG_ERR, "[VelaWear] State manager init failed: %d\n", ret);
   186	      return ret;
   187	    }
   188	  agent->state = state_manager_get_state(&agent->state_mgr);
   189	
   190	  /* Initialize the LCD/LVGL status page on the main thread.  LVGL keeps
   191	   * context in task-local storage, so timer handling stays in this thread. */
   192	
   193	  ret = display_manager_init(&agent->display, &agent->state_mgr);
   194	  if (ret < 0)
   195	    {
   196	      syslog(LOG_WARNING, "[VelaWear] Display init failed: %d\n", ret);
   197	      /* Non-fatal: the agent remains usable without a display. */
   198	    }
   199	
   200	  /* Initialize decision engine */
   201	
   202	  ret = decision_engine_init(&agent->engine, &agent->config);
