    63	
    64	int event_manager_dispatch(velawear_events_t *events,
    65	                           velawear_event_t *event)
    66	{
    67	  int ret;
    68	
    69	  if (events == NULL || event == NULL)
    70	    {
    71	      return VELAWEAR_ERR_INVAL;
    72	    }
    73	
    74	  pthread_mutex_lock(&events->lock);
    75	
    76	  for (int i = 0; i < events->handler_count; i++)
    77	    {
    78	      if (events->handlers[i].event_type == event->type ||
    79	          events->handlers[i].event_type == VELAWEAR_EVENT_NONE)
    80	        {
    81	          ret = events->handlers[i].handler(event,
    82	                                            events->handlers[i].context);
    83	          if (ret < 0)
    84	            {
    85	              syslog(LOG_WARNING,
    86	                     "[EventMgr] Handler %d returned error: %d\n",
    87	                     i, ret);
    88	            }
    89	        }
    90	    }
    91	
    92	  pthread_mutex_unlock(&events->lock);
    93	  return VELAWEAR_OK;
    94	}
