    97	int event_manager_init(velawear_events_t *events)
    98	{
    99	  struct mq_attr attr;
   100	
   101	  memset(events, 0, sizeof(velawear_events_t));
   102	
   103	  /* Initialize mutex */
   104	
   105	  pthread_mutex_init(&events->lock, NULL);
   106	
   107	  /* Create message queue */
   108	
   109	  attr.mq_flags = 0;
   110	  attr.mq_maxmsg = EVENT_QUEUE_SIZE;
   111	  /* Keep the mqueue payload within CONFIG_MQ_MAXMSGSIZE.  Events are
   112	   * copied through heap-backed pointers so the full event union can
   113	   * remain available to handlers. */
   114	  attr.mq_msgsize = sizeof(uintptr_t);
   115	  attr.mq_curmsgs = 0;
   116	
   117	  /* A crashed instance may leave pointer messages behind.  Remove the
   118	   * old queue before creating a fresh one for this process. */
   119	  mq_unlink("/velawear_events");
   120	
   121	  events->queue = mq_open("/velawear_events", O_CREAT | O_RDWR, 0644,
   122	                          &attr);
   123	  if (events->queue == (mqd_t)-1)
   124	    {
   125	      syslog(LOG_ERR, "[EventMgr] Failed to create message queue: %d\n",
   126	             errno);
   127	      return VELAWEAR_ERR_IO;
   128	    }
   129	
   130	  events->running = false;
   131	  events->handler_count = 0;
   132	
   133	  syslog(LOG_INFO, "[EventMgr] Initialized\n");
   134	  return VELAWEAR_OK;
   135	}
   136	
   137	int event_manager_start(velawear_events_t *events)
   138	{
   139	  int ret;
   140	
   141	  if (events->running)
   142	    {
   143	      return VELAWEAR_ERR_BUSY;
   144	    }
   145	
   146	  events->running = true;
   147	
   148	  ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
   149	  if (ret != 0)
   150	    {
   151	      syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
   152	      events->running = false;
   153	      return VELAWEAR_ERR_IO;
   154	    }
   155	
   156	  syslog(LOG_INFO, "[EventMgr] Started\n");
   157	  return VELAWEAR_OK;
   158	}
