   160	void event_manager_cleanup(velawear_events_t *events)
   161	{
   162	  if (events->running)
   163	    {
   164	      events->running = false;
   165	      pthread_join(events->thread, NULL);
   166	    }
   167	
   168	  if (events->queue != (mqd_t)-1)
   169	    {
   170	      mq_close(events->queue);
   171	      mq_unlink("/velawear_events");
   172	    }
   173	
