    47	static void update_motion_state(imu_sensor_t *imu, imu_data_t *data)
    48	{
    49	  float accel_mag = calculate_magnitude(data->accel_x,
    50	                                        data->accel_y,
    51	                                        data->accel_z);
    52	  float gyro_mag = calculate_magnitude(data->gyro_x,
    53	                                       data->gyro_y,
    54	                                       data->gyro_z);
    55	
    56	  /* Check for fall detection (sudden high acceleration) */
    57	
    58	  if (accel_mag > imu->threshold_fall)
    59	    {
    60	      imu->motion.fall_detected = true;
    61	      syslog(LOG_WARNING, "[IMU] Fall detected! Accel: %.2f\n", accel_mag);
    62	    }
    63	
    64	  /* Check for running (high acceleration + gyro) */
    65	
    66	  if (accel_mag > imu->threshold_run && gyro_mag > 1.0f)
    67	    {
    68	      imu->motion.is_running = true;
    69	      imu->motion.is_moving = true;
    70	      imu->motion.last_motion_time = time(NULL);
    71	      imu->motion.motion_count++;
    72	    }
    73	  /* Check for moving (moderate acceleration) */
    74	
    75	  else if (accel_mag > imu->threshold_move)
    76	    {
    77	      imu->motion.is_moving = true;
    78	      imu->motion.is_running = false;
    79	      imu->motion.last_motion_time = time(NULL);
    80	      imu->motion.motion_count++;
    81	    }
    82	  else
    83	    {
    84	      /* No significant motion */
    85	
    86	      if (time(NULL) - imu->motion.last_motion_time > 5)
    87	        {
    88	          imu->motion.is_moving = false;
    89	          imu->motion.is_running = false;
    90	        }
    91	    }
    92	
    93	  imu->motion.motion_intensity = accel_mag;
    94	}
