445	static int velawear_event_handler(velawear_event_t *event, void *context)
446	{
447	  velawear_agent_t *agent = (velawear_agent_t *)context;
448	  velawear_state_t state;
449	  velawear_action_t action;
450	  int rule_id;
451	  int ret;
452	
453	  ret = state_manager_update_from_event(&agent->state_mgr, event);
454	  if (ret < 0)
455	    {
456	      return ret;
457	    }
458	
459	  state = state_manager_get_state(&agent->state_mgr);
460	  agent->state = state;
461	  rule_id = decision_engine_evaluate(&agent->engine, &state, event);
462	
463	  /* Every matched rule produces a traceable action.  Rule-specific handlers
464	   * can replace this log action later without changing the event pipeline. */
465	  if (rule_id >= 0 && event->type != VELAWEAR_EVENT_IMU_DATA &&
466	      event->type != VELAWEAR_EVENT_FALL)
467	    {
468	      memset(&action, 0, sizeof(action));
469	      action.type = VELAWEAR_ACTION_LOG;
470	      action.priority = event->priority;
471	      ret = action_manager_execute(&agent->actions, &action);
472	      if (ret < 0)
473	        {
474	          return ret;
475	        }
476	    }
477	
478	  /* The action manager worker performs callbacks; wake it after evaluation. */
479	  return action_manager_process(&agent->actions);
480	}
