      if (age > 5000 && !reported_stall)
        {
          syslog(LOG_ERR,
                 "[Watchdog] Main loop heartbeat stalled (%lu ms)\\n",
                 (unsigned long)age);
          reported_stall = true;
        }
      else if (age <= 5000)
        {
          reported_stall = false;
        }

      /* Keep the hardware watchdog alive even while the main loop is
       * blocked waiting for an event.  The software heartbeat still records
