L185: pub fn recv_response<F: ChipFrameFormat, R: Read>(
L186:     reader: &mut BufReader<R>,
L187: ) -> Result<SifliUartResponse> {
L188:     let start_time = Instant::now();
L189:     let mut temp: Vec<u8> = vec![];
L190: 
L191:     // 步骤1: 找到帧起始标记 (START_WORD)
L192:     tracing::debug!("Waiting for frame start marker...");
L193:     let mut buffer = vec![];
L194:     loop {
L195:         if start_time.elapsed() >= DEFUALT_RECV_TIMEOUT {
L196:             tracing::warn!(
L197:                 "Receive timeout: {} seconds",
L198:                 DEFUALT_RECV_TIMEOUT.as_secs()
L199:             );
L200:             return Err(RecvError::Timeout.into());
L201:         }
L202:         let mut byte = [0; 1];
L203:         match reader.read_exact(&mut byte) {
L204:             Ok(_) => {
L205:                 // 处理帧检测逻辑
L206:                 if byte[0] == START_WORD[0] || (buffer.len() == 1 && byte[0] == START_WORD[1]) {
L207:                     buffer.push(byte[0]);
L208:                     // 检查是否找到完整的START_WORD
L209:                     if buffer.ends_with(&START_WORD) {
L210:                         tracing::debug!("Frame start marker found: {:02X?}", START_WORD);
L211:                         break;
L212:                     }
L213:                 } else {
L214:                     // 重置缓冲区
L215:                     buffer.clear();
L216:                 }
L217:                 // 缓冲区超过2个字节但没有匹配START_WORD，清除旧数据
L218:                 if buffer.len() > 2 {
L219:                     buffer.clear();
L220:                 }
L221:             }
L222:             Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
L223:                 // 对于非阻塞IO，继续尝试
L224:                 continue;
L225:             }
L226:             Err(e) if is_cancelled_io_error(&e) => {
L227:                 return Err(RecvError::Cancelled.into());
L228:             }
L229:             Err(e) => {
L230:                 tracing::error!("Error reading frame start marker: {}", e);
L231:                 continue; // 继续尝试读取下一个字节
L232:             }
L233:         }
L234:     }
L235:     temp.extend_from_slice(&buffer);
L236: 
L237:     // 步骤2: 使用芯片特定的帧头解析
L238:     let payload_size = F::parse_frame_header(reader)?;
L239:     tracing::debug!("Received packet length: {} bytes", payload_size);
L240: 
L241:     // 步骤3: 读取有效载荷数据
L242:     tracing::debug!("Reading payload data ({} bytes)...", payload_size);
L243:     let mut recv_data = vec![];
L244:     while recv_data.len() < payload_size {
L245:         let mut byte = [0; 1];
L246:         match reader.read_exact(&mut byte) {
L247:             Ok(_) => {
L248:                 recv_data.push(byte[0]);
L249:             }
L250:             Err(e) if is_cancelled_io_error(&e) => {
L251:                 return Err(RecvError::Cancelled.into());
L252:             }
L253:             Err(e) => {
L254:                 tracing::error!("Failed to read payload data: {}", e);
L255:                 return Err(RecvError::ReadError(e).into());
L256:             }
L257:         }
L258:     }
L259:     temp.extend_from_slice(&recv_data);
L260: 
L261:     // 步骤4: 解析响应数据
L262:     if recv_data.is_empty() {
L263:         tracing::error!("Received empty payload data");
L264:         return Err(RecvError::InvalidResponse(0).into());
L265:     }
L266:     let response_code = recv_data[0];
L267:     match response_code {
L268:         0xD1 => {
L269:             tracing::info!("Received Enter command response");
L270:             Ok(SifliUartResponse::Enter)
L271:         }
L272:         0xD0 => {
L273:             tracing::info!("Received Exit command response");
L274:             Ok(SifliUartResponse::Exit)
L275:         }
L276:         0xD2 => {
L277:             // 提取数据部分，跳过响应代码和最后的校验字节
L278:             let data = if recv_data.len() > 1 {
L279:                 recv_data[1..recv_data.len() - 1].to_vec()
L280:             } else {
L281:                 Vec::new()
L282:             };
L283:             tracing::info!(
L284:                 "Received memory read response, data length: {} bytes",
L285:                 data.len()
L286:             );
L287:             Ok(SifliUartResponse::MEMRead { data })
L288:         }
L289:         0xD3 => {
L290:             tracing::info!("Received memory write response");
L291:             Ok(SifliUartResponse::MEMWrite)
L292:         }
L293:         _ => {
L294:             tracing::error!("Received unknown response code: {:#04X}", response_code);
L295:             Err(RecvError::InvalidResponse(response_code).into())
L296:         }
L297:     }
L298: }
