/****************************************************************************
 * Name: up_allocate_heap/up_allocate_kheap
 *
 * Description:
 *   This function will be called to dynamically set aside the heap region.
 *
 *   - For the normal "flat" build, this function returns the size of the
 *     single heap.
 *   - For the protected build (CONFIG_BUILD_PROTECTED=y) with both kernel-
 *     and user-space heaps (CONFIG_MM_KERNEL_HEAP=y), this function
 *     provides the size of the unprotected, user-space heap.
 *   - For the kernel build (CONFIG_BUILD_KERNEL=y), this function provides
 *     the size of the protected, kernel-space heap.
 *
 *   If a protected kernel-space heap is provided, the kernel heap must be
 *   allocated by an analogous up_allocate_kheap(). A custom version of this
 *   file is needed if memory protection of the kernel heap is required.
 *
 *   The following memory map is assumed for the flat build:
 *
 *     .data region.  Size determined at link time.
 *     .bss  region  Size determined at link time.
 *     IDLE thread stack.  Size determined by CONFIG_IDLETHREAD_STACKSIZE.
 *     Heap.  Extends to the end of SRAM.
 *
 *   The following memory map is assumed for the kernel build:
 *
 *     Kernel .data region.  Size determined at link time.
 *     Kernel .bss  region  Size determined at link time.
HAL_StatusTypeDef HAL_Init(void)
{
    HAL_StatusTypeDef  status = HAL_OK;

    /* Configure Flash prefetch, Instruction cache, Data cache */
    /* Default configuration at reset is:                      */
    /* - Prefetch disabled                                     */
    /* - Instruction cache enabled                             */
    /* - Data cache enabled                                    */
#if (INSTRUCTION_CACHE_ENABLE == 0)
//   __HAL_FLASH_INSTRUCTION_CACHE_DISABLE();
#endif /* INSTRUCTION_CACHE_ENABLE */

#if (DATA_CACHE_ENABLE == 0)
//   __HAL_FLASH_DATA_CACHE_DISABLE();
#endif /* DATA_CACHE_ENABLE */

#if (PREFETCH_ENABLE != 0)
    __HAL_FLASH_PREFETCH_BUFFER_ENABLE();
#endif /* PREFETCH_ENABLE */

#if defined(HAL_V2D_GPU_MODULE_ENABLED)
    HAL_RCC_ResetModule(RCC_MOD_GPU);
#endif

    HAL_PreInit();

#ifdef SOC_BF0_HCPU
    if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
    {
//TODO: 52x also needs RC48
//#ifndef SF32LB52X
        // Except Standby mode, all other boot mode need to re-calibrate RC48
        status = HAL_RCC_CalibrateRC48();
#ifndef TARMAC
        HAL_ASSERT(HAL_OK == status);
#endif
//#endif /* SF32LB52X */
    }
#endif /* SOC_BF0_HCPU */

    HAL_PostMspInit();
    HAL_RCC_Init();

#ifdef SOC_BF0_HCPU
    if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
    {
        HAL_PMU_Init();
    }
#endif /* SOC_BF0_HCPU */

#ifdef HAL_ADC_MODULE_ENABLED
    HAL_ADC_HwInit(PM_STANDBY_BOOT != SystemPowerOnModeGet());
#endif /* HAL_ADC_MODULE_ENABLED */

    /* Set Interrupt Group Priority */
    HAL_NVIC_SetPriorityGrouping(NVIC_PRIORITYGROUP_4);

#ifndef NONE_HAL_TICK_INIT
    /* Use SysTick as time base source and configure 1ms tick (default clock after Reset is MSI) */
    if (HAL_InitTick(TICK_INT_PRIORITY) != HAL_OK)
    {
        status = HAL_ERROR;
    }
    else
#endif
    {
#ifdef SOC_BF0_HCPU
        /* init AES_ACC as normal mode */
        __HAL_SYSCFG_CLEAR_SECURITY();
        HAL_EFUSE_Init();
#endif
    }

    /* Return function status */
    return status;
}

