    21	static void display_gesture_cb(lv_event_t *event)
    22	{
    23	  velawear_display_t *display;
    24	  lv_indev_t *indev;
    25	  lv_dir_t dir = LV_DIR_NONE;
    26	  lv_point_t point;
    27	  velawear_event_t touch_event;
    28	  lv_event_code_t code;
    29	
    30	  display = (velawear_display_t *)lv_event_get_user_data(event);
    31	  indev = lv_indev_active();
    32	  if (display == NULL || indev == NULL)
    33	    {
    34	      return;
    35	    }
    36	
    37	  code = lv_event_get_code(event);
    38	  lv_indev_get_point(indev, &point);
    39	  if (code == LV_EVENT_GESTURE)
    40	    {
    41	      dir = lv_indev_get_gesture_dir(indev);
    42	    }
    43	
    44	  memset(&touch_event, 0, sizeof(touch_event));
    45	  touch_event.type = VELAWEAR_EVENT_TOUCH;
    46	  touch_event.priority = VELAWEAR_PRIORITY_NORMAL;
    47	  touch_event.timestamp = display_now_ms();
    48	  touch_event.data.touch.x = point.x;
    49	  touch_event.data.touch.y = point.y;
    50	  touch_event.data.touch.gesture = code == LV_EVENT_GESTURE ?
    51	                                    (int)dir : (int)code;
    52	  if (display->events != NULL &&
    53	      event_manager_push(display->events, &touch_event) < 0)
    54	    {
    55	      syslog(LOG_WARNING, "[Display] Failed to queue touch gesture\n");
    56	    }
    57	
    58	  if (code == LV_EVENT_CLICKED)
    59	    {
    60	      /* A short press returns to the always-available watchface. */
    61	      display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
    62	    }
    63	  else if (code == LV_EVENT_LONG_PRESSED)
    64	    {
    65	      /* Long press opens settings until a dedicated settings menu exists. */
    66	      display_manager_set_page(display, VELAWEAR_PAGE_SETTINGS);
    67	    }
    68	  else if ((dir & LV_DIR_LEFT) != 0 || (dir & LV_DIR_TOP) != 0)
    69	    {
    70	      display_manager_next_page(display);
    71	    }
    72	  else if ((dir & LV_DIR_RIGHT) != 0 || (dir & LV_DIR_BOTTOM) != 0)
    73	    {
    74	      display_manager_previous_page(display);
    75	    }
    76	}
