   292	      heart_rate = state.heart_rate > 0.0f ? "available" : "--";
   293	      snprintf(metrics, sizeof(metrics),
   294	               "Motion: %s\nBattery: %lu%%%s\nHeart rate: %s",
   295	               motion, (unsigned long)state.battery_level,
   296	               state.is_charging ? " (charging)" : "", heart_rate);
   297	      display_render_page(display, &state);
   298	      lv_label_set_text(display->status_label, "Agent running");
   299	      display->last_update_ms = now;
   300	    }
   301	
   302	  lv_timer_handler();
   303	}
