   306	void display_manager_set_page(velawear_display_t *display,
   307	                              velawear_display_page_t page)
   308	{
   309	  if (display == NULL || !display->initialized || page >= VELAWEAR_PAGE_COUNT)
   310	    {
   311	      return;
   312	    }
   313	
   314	  display->page_index = (uint8_t)page;
   315	  display->metrics_label = display->page_content[display->page_index];
   316	  if (display->tileview != NULL)
   317	    {
   318	      lv_tileview_set_tile_by_index(display->tileview, display->page_index, 0,
   319	                                    LV_ANIM_ON);
   320	    }
   321	  display->last_update_ms = 0;
   322	}
