   324	void display_manager_next_page(velawear_display_t *display)
   325	{
   326	  if (display == NULL || !display->initialized)
   327	    {
   328	      return;
   329	    }
   330	
   331	  display_manager_set_page(display,
   332	                           (velawear_display_page_t)
   333	                           ((display->page_index + 1) % VELAWEAR_PAGE_COUNT));
   334	}
