   336	void display_manager_previous_page(velawear_display_t *display)
   337	{
   338	  if (display == NULL || !display->initialized)
   339	    {
   340	      return;
   341	    }
   342	
   343	  display_manager_set_page(display,
   344	                           (velawear_display_page_t)
   345	                           ((display->page_index + VELAWEAR_PAGE_COUNT - 1) %
   346	                            VELAWEAR_PAGE_COUNT));
   347	}
   348	
   349	void display_manager_show_alert(velawear_display_t *display,
   350	                                const char *message)
   351	{
   352	  if (display == NULL || !display->initialized || message == NULL)
   353	    {
   354	      return;
   355	    }
   356	
   357	  pthread_mutex_lock(&display->lock);
   358	  strncpy(display->pending_alert, message,
   359	          sizeof(display->pending_alert) - 1);
   360	  display->pending_alert[sizeof(display->pending_alert) - 1] = '\0';
   361	  display->alert_pending = true;
   362	  pthread_mutex_unlock(&display->lock);
   363	}
   364	
   365	void display_manager_cleanup(velawear_display_t *display)
   366	{
   367	  if (display == NULL || !display->initialized)
   368	    {
   369	      return;
   370	    }
   371	
   372	  /* The SF32 framebuffer driver owns its driver_data allocation.  Clear
   373	   * the callback-owned pointer before LVGL deletes the display to avoid a
   374	   * second free during shutdown. */
   375	  if (display->lv_result.disp != NULL)
   376	    {
   377	      lv_display_set_driver_data(display->lv_result.disp, NULL);
   378	    }
   379	
   380	  lv_nuttx_deinit(&display->lv_result);
   381	  lv_deinit();
   382	  pthread_mutex_destroy(&display->lock);
   383	  display->initialized = false;
   384	  syslog(LOG_INFO, "[Display] LCD/LVGL cleaned up\n");
   385	}
