   565	      return ret;
   566	    }
   567	  agent->state = state_manager_get_state(&agent->state_mgr);
   568	
   569	  /* Initialize the LCD/LVGL status page on the main thread.  LVGL keeps
   570	   * context in task-local storage, so timer handling stays in this thread. */
   571	
   572	  ret = display_manager_init(&agent->display, &agent->state_mgr,
   573	                             &agent->events);
   574	  if (ret < 0)
   575	    {
   576	      syslog(LOG_WARNING, "[VelaWear] Display init failed: %d\n", ret);
   577	      /* Non-fatal: the agent remains usable without a display. */
   578	    }
