   338	  if (agent == NULL)
   339	    {
   340	      return;
   341	    }
   342	
   343	  agent->watchdog_last_main_ms = velawear_now_ms();
   344	  if (agent->watchdog_active && agent->watchdog_fd >= 0)
   345	    {
   346	      if (ioctl(agent->watchdog_fd, WDIOC_KEEPALIVE, 0) < 0)
   347	        {
   348	          syslog(LOG_WARNING, "[Watchdog] Keepalive failed: %d\n", errno);
   349	        }
   350	    }
   351	}
   352	
   353	static void *velawear_watchdog_thread(void *context)
   354	{
   355	  velawear_agent_t *agent = (velawear_agent_t *)context;
   356	  bool reported_stall = false;
   357	
   358	  syslog(LOG_INFO, "[Watchdog] Software monitor started\n");
   359	  while (agent->running)
   360	    {
   361	      uint32_t age = velawear_now_ms() - agent->watchdog_last_main_ms;
   362	
   363	      if (age > 5000 && !reported_stall)
   364	        {
   365	          syslog(LOG_ERR,
   366	                 "[Watchdog] Main loop heartbeat stalled (%lu ms)\n",
   367	                 (unsigned long)age);
   368	          reported_stall = true;
   369	        }
   370	      else if (age <= 5000)
   371	        {
   372	          reported_stall = false;
   373	        }
   374	
   375	      usleep(1000000);
   376	    }
   377	
   378	  syslog(LOG_INFO, "[Watchdog] Software monitor stopped\n");
   379	  return NULL;
   380	}
   381	
   382	static int velawear_watchdog_start_software(velawear_agent_t *agent)
   383	{
   384	  int ret;
   385	
   386	  agent->watchdog_last_main_ms = velawear_now_ms();
   387	  ret = pthread_create(&agent->watchdog_thread, NULL,
   388	                       velawear_watchdog_thread, agent);
   389	  if (ret != 0)
   390	    {
   391	      syslog(LOG_WARNING, "[Watchdog] Software monitor start failed: %d\n",
   392	             ret);
   393	      return ret;
   394	    }
   395	
   396	  agent->watchdog_thread_started = true;
   397	  return VELAWEAR_OK;
   398	}
   399	
   400	static int velawear_watchdog_start(velawear_agent_t *agent)
   401	{
   402	  int timeout_ms = 5000;
   403	  int ret;
   404	
   405	  if (agent == NULL)
   406	    {
   407	      return VELAWEAR_ERR_INVAL;
   408	    }
   409	
   410	  agent->watchdog_fd = open("/dev/watchdog0", O_RDWR);
   411	  if (agent->watchdog_fd < 0)
   412	    {
   413	      syslog(LOG_WARNING, "[Watchdog] /dev/watchdog0 unavailable: %d\n",
   414	             errno);
   415	      ret = velawear_watchdog_start_software(agent);
   416	      if (ret == VELAWEAR_OK)
   417	        {
   418	          syslog(LOG_INFO, "[Watchdog] Software-only monitor enabled\n");
   419	        }
   420	      return VELAWEAR_OK;
   421	    }
   422	
   423	  if (ioctl(agent->watchdog_fd, WDIOC_SETTIMEOUT, timeout_ms) < 0 ||
   424	      ioctl(agent->watchdog_fd, WDIOC_START, 0) < 0)
   425	    {
   426	      syslog(LOG_WARNING, "[Watchdog] Hardware watchdog start failed: %d\n",
   427	             errno);
   428	      close(agent->watchdog_fd);
   429	      agent->watchdog_fd = -1;
   430	      ret = velawear_watchdog_start_software(agent);
   431	      if (ret == VELAWEAR_OK)
   432	        {
   433	          syslog(LOG_INFO, "[Watchdog] Software-only monitor enabled\n");
   434	        }
   435	      return VELAWEAR_OK;
   436	    }
   437	
   438	  agent->watchdog_active = true;
   439	  ret = velawear_watchdog_start_software(agent);
   440	  if (ret != VELAWEAR_OK)
   441	    {
   442	      ioctl(agent->watchdog_fd, WDIOC_STOP, 0);
   443	      close(agent->watchdog_fd);
   444	      agent->watchdog_fd = -1;
   445	      agent->watchdog_active = false;
   446	      return VELAWEAR_OK;
   447	    }
   448	
   449	  syslog(LOG_INFO, "[Watchdog] Hardware watchdog started (%d ms)\n",
   450	         timeout_ms);
   451	  return VELAWEAR_OK;
   452	}
