   700	
   701	static int velawear_start(velawear_agent_t *agent)
   702	{
   703	  int ret;
   704	
   705	  /* The main loop owns event queue consumption.  Do not start a second
   706	   * consumer thread for the same mqueue. */
   707	
   708	  /* Start action manager thread. */
   709	
   710	  ret = action_manager_start(&agent->actions);
   711	  if (ret < 0)
   712	    {
   713	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
   714	      return ret;
   715	    }
   716	
   717	  /* Decision rules are evaluated synchronously for each event. */
   718	
   719	  /* Mark agent as running before starting the sensor producer. */
   720	
   721	  agent->running = true;
   722	  ret = velawear_watchdog_start(agent);
   723	  if (ret < 0)
   724	    {
   725	      agent->running = false;
   726	      return ret;
   727	    }
   728	
   729	  if (agent->imu.initialized)
   730	    {
   731	      ret = pthread_create(&agent->imu_thread, NULL,
   732	                           velawear_imu_thread, agent);
   733	      if (ret != 0)
   734	        {
   735	          agent->running = false;
   736	          syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
   737	          return VELAWEAR_ERR_IO;
   738	        }
   739	      agent->imu_thread_started = true;
   740	    }
   741	
   742	  return VELAWEAR_OK;
   743	}
   744	
   745	static void velawear_cleanup(velawear_agent_t *agent)
   746	{
   747	  /* Stop subsystems in reverse order */
   748	
   749	  agent->running = false;
   750	  velawear_watchdog_stop(agent);
   751	  if (agent->imu_thread_started)
   752	    {
   753	      pthread_join(agent->imu_thread, NULL);
   754	      agent->imu_thread_started = false;
   755	    }
   756	
   757	  velawear_llm_cleanup(&agent->llm);
   758	  audio_sensor_cleanup(&agent->audio);
   759	  imu_sensor_cleanup(&agent->imu);
   760	  action_manager_cleanup(&agent->actions);
   761	  event_manager_cleanup(&agent->events);
   762	  decision_engine_cleanup(&agent->engine);
   763	  display_manager_cleanup(&agent->display);
   764	  state_manager_cleanup(&agent->state_mgr);
   765	  velawear_config_cleanup(&agent->config);
   766	}
