   771	  g_agent.running = false;
   772	}
   773	
   774	static int velawear_event_handler(velawear_event_t *event, void *context)
   775	{
   776	  velawear_agent_t *agent = (velawear_agent_t *)context;
   777	  velawear_state_t state;
   778	  velawear_action_t action;
   779	  int rule_id;
   780	  int ret;
   781	
   782	  ret = state_manager_update_from_event(&agent->state_mgr, event);
   783	  if (ret < 0)
   784	    {
   785	      return ret;
   786	    }
   787	
   788	  state = state_manager_get_state(&agent->state_mgr);
   789	  agent->state = state;
   790	  rule_id = decision_engine_evaluate(&agent->engine, &state, event);
   791	
   792	  /* Every matched rule produces a traceable action.  Rule-specific handlers
   793	   * can replace this log action later without changing the event pipeline. */
   794	  if (rule_id >= 0 && event->type != VELAWEAR_EVENT_IMU_DATA &&
   795	      event->type != VELAWEAR_EVENT_FALL)
   796	    {
   797	      memset(&action, 0, sizeof(action));
   798	      action.type = VELAWEAR_ACTION_LOG;
   799	      action.priority = event->priority;
   800	      ret = action_manager_execute(&agent->actions, &action);
   801	      if (ret < 0)
   802	        {
   803	          return ret;
   804	        }
   805	    }
   806	
   807	  /* The action manager worker performs callbacks; wake it after evaluation. */
   808	  return action_manager_process(&agent->actions);
   809	}
