 | void imgFileObj::loadBMP()
 | {
 | unsigned char fileHdr[14];
 | unsigned char bmpInfo[40];
 | 
 | ifstream fs(_pImgFilePath, ifstream::in | ifstream::binary);
 | if (!fs.is_open()) {
 | fprintf(stderr, "Error: cannot open file %s\n", _pImgFilePath);
 | }
 | 
 | //get bitmap information
 | fs.read((char *)fileHdr, sizeof(fileHdr));
 | fs.read((char *)bmpInfo, sizeof(bmpInfo));
 | 
 | if (fileHdr[0] != 'B' && fileHdr[1] != 'M') { //'BM'
 | fprintf(stderr, "Error: image file %s is not a valid BMP file\n", _pImgFileName);
 | fs.close();
 | return;
 | }
 | 
 | imgWidth = *((int*)&bmpInfo[4]);
 | int height = *((int*)&bmpInfo[8]);
 | unsigned short biBitCount = *((unsigned short*)&bmpInfo[14]);
 | unsigned int biCompression = *((unsigned int*)&bmpInfo[16]);
 | unsigned int bfOffBits = *((unsigned int*)&fileHdr[10]);
 | 
 | // upside down image?
 | bool invertedImage = false;
 | if(height < 0) {
 | invertedImage = true;
 | height = -height;
 | }
 | imgHeight = (unsigned int)height;
 | 
 | // read pixels
 | if (biBitCount == 24) {
 | numComponents = 3;
 | imgFormat = CLIMAGELOAD_RGB24;
 | componentOrder = CLIMAGELOAD_R_G_B;
 | dataType = CLIMAGELOAD_UINT8;
 | } else if (biBitCount == 32 && biCompression == 0) {
 | numComponents = 4;
 | imgFormat = CLIMAGELOAD_RGBA32;
 | componentOrder = CLIMAGELOAD_R_G_B_A;
 | dataType = CLIMAGELOAD_UINT8;
 | } else {
 | fprintf(stderr, "Error: imgFileObj::loadBMP() cannot handle biBitCount=%d\n", biBitCount);
 | fs.close();
 | return;
 | }
 | 
 | _pBuffSize = imgWidth * imgHeight * numComponents;
 | _pImgData = malloc(_pBuffSize);
 | char *pixels = (char*)_pImgData;
 | 
 | int bytesPerRow = imgWidth * numComponents;
 | int scanLine;
 | 
 | if( (bytesPerRow % 4) != 0 ) { // if not aligned to 4 bytes (32-bits)
 | scanLine = (bytesPerRow & 0xFFFFFFFC) + 0x4; // BMP are 32-bit align, calculate scan line size or pitch
 | } else {
 | scanLine = bytesPerRow;
 | }
 | 
 | for (unsigned int i=0; i<imgHeight; i++) {
 | 
 | fs.seekg(bfOffBits + i * scanLine, ifstream::beg);
 | 
 | for (unsigned int j=0; j<imgWidth; j++) {
 | 
 | // BGR, BGR, ...
 | fs.read(&pixels[2], 1); // B
 | fs.read(&pixels[1], 1); // G
 | fs.read(&pixels[0], 1); // R
 | 
 | if (numComponents == 3) {
 | pixels += 3;
 | } else if (numComponents == 4) {
 | pixels += 4;
 | fs.read(&pixels[3], 1); // A
 | }
 | }
 | }
 | 
 | if (invertedImage) {
 | // TODO: make it upside-down
 | }
 | 
 | _pImgLoaded = true;
 | }
