 | void imgFileObj::loadPPM()
 | {
 | int width, height, max;
 | 
 | ifstream fs(_pImgFilePath, ifstream::in | ifstream::binary);
 | if (fs.is_open()) {
 | 
 | char header[PGM_HEADER_LINE_SIZE];
 | fs.getline(header, PGM_HEADER_LINE_SIZE);
 | 
 | // make sure it's PPM binary format
 | if (strncmp(header, "P6", 2) == 0) {
 | 
 | int count=0;
 | while (count<3) {
 | 
 | fs.getline(header, PGM_HEADER_LINE_SIZE);
 | 
 | // skip comments
 | while (header[0] == '#') {
 | fs.getline(header, PGM_HEADER_LINE_SIZE);
 | }
 | 
 | // read width, height, maxval
 | if (count == 0) {
 | count += sscanf(header, "%d %d %d", &width, &height, &max);
 | } else if (count == 1) {
 | count += sscanf(header, "%d %d", &height, &max);
 | } else if (count == 2) {
 | count += sscanf(header, "%d", &max);
 | }
 | }
 | 
 | imgWidth = width;
 | imgHeight = height;
 | numComponents = 3;
 | imgFormat = CLIMAGELOAD_RGB24;
 | componentOrder = CLIMAGELOAD_R_G_B;
 | dataType = CLIMAGELOAD_UINT8;
 | 
 | _pBuffSize = imgWidth * imgHeight * numComponents;
 | _pImgData = (unsigned char*)malloc(_pBuffSize);
 | if (_pImgData != NULL) {
 | fs.read((char*)_pImgData, _pBuffSize);
 | _pImgLoaded = true;
 | }
 | fs.close();
 | }
 | else {
 | fprintf(stderr, "Error: %s is not a valid PPM binary file.\n", _pImgFileName);
 | }
 | }
 | else {
 | fprintf(stderr, "Error: cannot open file %s\n", _pImgFilePath);
 | }
 | }
