 | void imgFileObj::loadYUVFrame
 | (
 | unsigned int frameSize, // size of raw data to read
 | unsigned int frameNum // frame number (=0 for single frame image)
 | )
 | {
 | ifstream fs(_pImgFilePath, ifstream::in | ifstream::binary);
 | if (!fs.is_open()) {
 | fprintf(stderr, "Error: cannot open file %s\n", _pImgFilePath);
 | }
 | 
 | fs.seekg(frameSize * frameNum, ifstream::beg);
 | 
 | // if already loaded, free memory
 | if (_pImgLoaded) {
 | free(_pImgData);
 | _pImgLoaded = false;
 | }
 | 
 | _pImgData = (unsigned char *)malloc(frameSize);
 | if (_pImgData != NULL) {
 | fs.read((char*)_pImgData, frameSize);
 | _pFrameNum = frameNum;
 | _pBuffSize = frameSize;
 | _pImgLoaded = true;
 | }
 | }
