 | void imgFileObj::saveBMP
 | (
 | char *fileName,
 | void *data,
 | unsigned int width,
 | unsigned int height,
 | unsigned int numComp
 | )
 | {
 | if (numComp < 3 || numComp > 4) {
 | fprintf(stderr,"Error: imgFileObj::saveBMP() cannot handle numComp=%d\n", numComp);
 | return;
 | }
 | 
 | unsigned char *srcBuf = (unsigned char *)data;
 | int buffSize = width * height * 3; // RGB mode
 | 
 | // convert to 24bpp in BGR corder (B in LSB)
 | unsigned char *imgBuf = (unsigned char*) malloc(buffSize);
 | for (unsigned int i=0; i<width*height; i++) {
 | imgBuf[i*3+0] = srcBuf[i*numComp+2]; // B
 | imgBuf[i*3+1] = srcBuf[i*numComp+1]; // G
 | imgBuf[i*3+2] = srcBuf[i*numComp+0]; // R
 | }
 | 
 | // pack header info
 | climageload_BITMAPFILEHEADER hdr;
 | climageload_BITMAPINFOHEADER info;
 | int headerSize = sizeof(hdr.bfType) + sizeof(hdr.bfSize) + sizeof(hdr.bfReserved1) +
 | sizeof(hdr.bfReserved2) + sizeof(hdr.bfOffBits);
 | 
 | hdr.bfType = 0x4D42; // "Microsoft "BM" = "MB"
 | hdr.bfSize = headerSize + sizeof(climageload_BITMAPINFOHEADER) + buffSize;
 | hdr.bfReserved1 = 0;
 | hdr.bfReserved2 = 0;
 | hdr.bfOffBits = headerSize + sizeof(climageload_BITMAPINFOHEADER);
 | 
 | info.biSize = sizeof(climageload_BITMAPINFOHEADER);
 | info.biWidth = width;
 | info.biHeight = height;
 | info.biPlanes = 1;
 | info.biBitCount = 24;
 | info.biCompression = 0;
 | fprintf(stderr,"\t\t[-saveIMG <y|n>\n");
 | fprintf(stderr,"\n\n");
 | fprintf(stderr,"For example:\n");
 | fprintf(stderr,"objectRemoval.exe -clImageFile WalkManStanford32x24.ppm -clMaskFile WalkManStanford32x24_mask.ppm -saveIMG y -clProgWithSrc y \n\n");
 | fprintf(stderr,"objectRemoval.exe -clImageFile WalkManStanford64x48.ppm -clMaskFile WalkManStanford64x48_mask.ppm -saveIMG y -clProgWithSrc y \n\n");
 | fprintf(stderr,"objectRemoval.exe -clImageFile WalkManStanford128x96.ppm -clMaskFile WalkManStanford128x96_mask.ppm -saveIMG y -clProgWithSrc y \n\n");
 | fprintf(stderr,"objectRemoval.exe -clImageFile WalkManStanford512x384.ppm -clMaskFile WalkManStanford512x384_mask.ppm -saveIMG y -clProgWithSrc y \n\n");
 | 
 | /*--------------------------------
 | Format of the image dataset name file colorCorrectionDataFile.txt
 | 
 | ColorCorrectionOffset.txt
 | warp
 | mask
 | ---------------------------------*/
 | 
 | fclose(stderr);
 | }
