  uint8_t page_index;
  uint32_t alert_until_ms;
  bool alert_active;
  bool alert_pending;
  char pending_alert[256];
  pthread_mutex_t lock;
} velawear_display_t;

int display_manager_init(velawear_display_t *display,
                         velawear_state_mgr_t *state_mgr,
