/* VelaWear Agent - LCD/LVGL display manager */

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <syslog.h>
#include <time.h>

#include <lvgl/lvgl.h>

#include "velawear.h"

#include "display_manager.h"

#define UI_BG_COLOR          0x000000
#define UI_SURFACE_COLOR     0x111827
#define UI_SURFACE_ALT_COLOR 0x1f2937
#define UI_PRIMARY_COLOR     0x007aff
#define UI_SUCCESS_COLOR     0x34c759
#define UI_WARNING_COLOR     0xff9500
#define UI_DANGER_COLOR      0xff3b30
#define UI_TEXT_COLOR        0xffffff
#define UI_MUTED_COLOR       0x8e8e93
#define UI_CARD_RADIUS       18

static uint32_t display_now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}


static void display_update_nav_dots(velawear_display_t *display)
{
  uint32_t i;

  if (display == NULL)
    {
      return;
    }

  for (i = 0; i < VELAWEAR_PAGE_COUNT; i++)
    {
      if (display->nav_dots[i] == NULL)
        {
          continue;
        }

      if (i == display->page_index)
        {
          lv_obj_set_width(display->nav_dots[i], 24);
          lv_obj_set_style_bg_color(display->nav_dots[i],
                                    lv_color_hex(UI_PRIMARY_COLOR), 0);
        }
      else
        {
          lv_obj_set_width(display->nav_dots[i], 8);
          lv_obj_set_style_bg_color(display->nav_dots[i],
                                    lv_color_hex(UI_MUTED_COLOR), 0);
        }
    }
}

static void display_restore_theme(velawear_display_t *display)
{
  lv_obj_t *screen;

  if (display == NULL)
    {
      return;
    }

  screen = lv_screen_active();
  lv_obj_set_style_bg_color(screen, lv_color_hex(UI_BG_COLOR), 0);
  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);
  if (display->status_label != NULL)
    {
      lv_obj_set_style_text_color(display->status_label,
                                  lv_color_hex(UI_MUTED_COLOR), 0);
    }
  if (display->page_title != NULL)
    {
      lv_obj_set_style_text_color(display->page_title,
                                  lv_color_hex(UI_PRIMARY_COLOR), 0);
    }
}

static void display_gesture_cb(lv_event_t *event)
{
  velawear_display_t *display;
  lv_indev_t *indev;
  lv_dir_t dir = LV_DIR_NONE;
  lv_point_t point;
  velawear_event_t touch_event;
  lv_event_code_t code;

  display = (velawear_display_t *)lv_event_get_user_data(event);
  indev = lv_indev_active();
  if (display == NULL || indev == NULL)
    {
      return;
    }

  code = lv_event_get_code(event);
  lv_indev_get_point(indev, &point);
  if (code == LV_EVENT_GESTURE)
    {
      dir = lv_indev_get_gesture_dir(indev);
    }

  memset(&touch_event, 0, sizeof(touch_event));
  touch_event.type = VELAWEAR_EVENT_TOUCH;
  touch_event.priority = VELAWEAR_PRIORITY_NORMAL;
  touch_event.timestamp = display_now_ms();
  touch_event.data.touch.x = point.x;
  touch_event.data.touch.y = point.y;
  touch_event.data.touch.gesture = code == LV_EVENT_GESTURE ?
                                    (int)dir : (int)code;
  if (display->events != NULL &&
      event_manager_push(display->events, &touch_event) < 0)
    {
      syslog(LOG_WARNING, "[Display] Failed to queue touch gesture\n");
    }

  if (code == LV_EVENT_CLICKED)
    {
      /* A short press returns to the always-available watchface. */
      display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
    }
  else if (code == LV_EVENT_LONG_PRESSED)
    {
      /* Long press opens settings until a dedicated settings menu exists. */
      display_manager_set_page(display, VELAWEAR_PAGE_SETTINGS);
    }
  else if ((dir & LV_DIR_LEFT) != 0 || (dir & LV_DIR_TOP) != 0)
    {
      display_manager_next_page(display);
    }
  else if ((dir & LV_DIR_RIGHT) != 0 || (dir & LV_DIR_BOTTOM) != 0)
    {
      display_manager_previous_page(display);
    }
}

static void display_create_ui(velawear_display_t *display)
{
  lv_obj_t *screen = lv_screen_active();
  lv_obj_t *tile;
  lv_obj_t *card;
  lv_obj_t *label;
  lv_obj_t *nav_bar;
  static const char *page_names[VELAWEAR_PAGE_COUNT] =
    {
      "Watchface", "Data Panel", "Task List", "Music", "Audio Test",
      "Settings"
    };

  lv_obj_set_style_bg_color(screen, lv_color_hex(UI_BG_COLOR), 0);
  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);

  display->status_label = lv_label_create(screen);
  lv_label_set_text(display->status_label, "AGENT  |  READY");
  lv_obj_set_style_text_color(display->status_label,
                              lv_color_hex(UI_MUTED_COLOR), 0);
  lv_obj_align(display->status_label, LV_ALIGN_TOP_LEFT, 20, 18);

  display->page_title = lv_label_create(screen);
  lv_label_set_text(display->page_title, page_names[0]);
  lv_obj_set_style_text_color(display->page_title,
                              lv_color_hex(UI_PRIMARY_COLOR), 0);
  lv_obj_align(display->page_title, LV_ALIGN_TOP_MID, 0, 18);

  display->tileview = lv_tileview_create(screen);
  lv_obj_set_size(display->tileview, lv_pct(92), lv_pct(70));
  lv_obj_align(display->tileview, LV_ALIGN_CENTER, 0, 4);

  for (uint32_t i = 0; i < VELAWEAR_PAGE_COUNT; i++)
    {
      tile = lv_tileview_add_tile(display->tileview, (uint8_t)i, 0,
                                  LV_DIR_HOR);
      lv_obj_set_style_bg_color(tile, lv_color_hex(UI_BG_COLOR), 0);
      lv_obj_set_style_bg_opa(tile, LV_OPA_COVER, 0);
      lv_obj_set_style_pad_all(tile, 14, 0);
      lv_obj_clear_flag(tile, LV_OBJ_FLAG_SCROLLABLE);

      card = lv_obj_create(tile);
      lv_obj_set_size(card, lv_pct(100), lv_pct(100));
      lv_obj_set_style_bg_color(card, lv_color_hex(UI_SURFACE_COLOR), 0);
      lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
      lv_obj_set_style_border_width(card, 1, 0);
      lv_obj_set_style_border_color(card,
                                    lv_color_hex(UI_SURFACE_ALT_COLOR), 0);
      lv_obj_set_style_radius(card, UI_CARD_RADIUS, 0);
      lv_obj_set_style_pad_all(card, 22, 0);
      lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);

      label = lv_label_create(card);
      lv_label_set_text(label, page_names[i]);
      lv_obj_set_width(label, lv_pct(100));
      lv_obj_set_style_text_color(label, lv_color_hex(UI_TEXT_COLOR), 0);
      lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, 0);
      lv_obj_align(label, LV_ALIGN_CENTER, 0, 0);
      display->page_content[i] = label;
    }

  lv_obj_add_event_cb(display->tileview, display_gesture_cb,
                      LV_EVENT_GESTURE, display);
  lv_obj_add_event_cb(display->tileview, display_gesture_cb,
                      LV_EVENT_CLICKED, display);
  lv_obj_add_event_cb(display->tileview, display_gesture_cb,
                      LV_EVENT_LONG_PRESSED, display);

  nav_bar = lv_obj_create(screen);
  lv_obj_set_size(nav_bar, 132, 12);
  lv_obj_align(nav_bar, LV_ALIGN_BOTTOM_MID, 0, -42);
  lv_obj_set_style_bg_opa(nav_bar, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(nav_bar, 0, 0);
  lv_obj_set_style_pad_all(nav_bar, 0, 0);
  lv_obj_set_flex_flow(nav_bar, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(nav_bar, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_column(nav_bar, 8, 0);
  lv_obj_clear_flag(nav_bar, LV_OBJ_FLAG_SCROLLABLE);

  for (uint32_t i = 0; i < VELAWEAR_PAGE_COUNT; i++)
    {
      display->nav_dots[i] = lv_obj_create(nav_bar);
      lv_obj_set_size(display->nav_dots[i], i == 0 ? 24 : 8, 8);
      lv_obj_set_style_radius(display->nav_dots[i], 4, 0);
      lv_obj_set_style_bg_color(display->nav_dots[i],
                                lv_color_hex(i == 0 ? UI_PRIMARY_COLOR :
                                             UI_MUTED_COLOR), 0);
      lv_obj_set_style_bg_opa(display->nav_dots[i], LV_OPA_COVER, 0);
      lv_obj_set_style_border_width(display->nav_dots[i], 0, 0);
      lv_obj_clear_flag(display->nav_dots[i], LV_OBJ_FLAG_SCROLLABLE);
    }

  display->metrics_label = display->page_content[0];
  display->page_hint = lv_label_create(screen);
  lv_label_set_text(display->page_hint, "Swipe to change  |  1/6");
  lv_obj_set_style_text_color(display->page_hint,
                              lv_color_hex(UI_MUTED_COLOR), 0);
  lv_obj_align(display->page_hint, LV_ALIGN_BOTTOM_MID, 0, -18);
}

static void display_render_page(velawear_display_t *display,
                                const velawear_state_t *state)
{
  char title[32];
  char content[256];
  char hint[48];
  time_t now;
  struct tm tm_now;
  const char *ble;
  const char *sedentary;

  if (display == NULL || state == NULL)
    {
      return;
    }

  ble = state->ble_connected ? "connected" : "offline";
  sedentary = state->is_moving ? "moving" : "monitoring";
  memset(&tm_now, 0, sizeof(tm_now));
  now = time(NULL);
  localtime_r(&now, &tm_now);

  switch ((velawear_display_page_t)display->page_index)
    {
      case VELAWEAR_PAGE_WATCHFACE:
