static void display_render_app(velawear_display_t *display,
                               const velawear_state_t *state)
{
  char content[384];
  uint32_t elapsed;
  uint32_t minutes;
  uint32_t seconds;
  uint32_t tenths;

  if (display == NULL || state == NULL || !display->detail_active ||
      display->metrics_label == NULL)
    {
      return;
    }

  content[0] = '\0';
  switch ((velawear_display_app_t)display->active_app)
    {
      case VELAWEAR_APP_AUDIO:
        snprintf(content, sizeof(content),
                 "SPEAKER\nReady for user test\n\nMICROPHONE\nTap to check device");
        break;

      case VELAWEAR_APP_MUSIC:
        snprintf(content, sizeof(content),
                 "Embedded Melody\n\nReady to play\nVolume 70%%");
        break;

      case VELAWEAR_APP_MOTION:
        snprintf(content, sizeof(content),
                 "Movement  %s\nRunning   %s\nMoves     %lu\nUptime    %lu s",
                 state->is_moving ? "ACTIVE" : "IDLE",
                 state->is_running ? "YES" : "NO",
                 (unsigned long)state->move_count_today,
                 (unsigned long)state->uptime_seconds);
        break;

      case VELAWEAR_APP_STOPWATCH:
        elapsed = display->stopwatch_elapsed_ms;
        if (display->stopwatch_running)
          {
            elapsed += display_now_ms() - display->stopwatch_started_ms;
          }
        minutes = elapsed / 60000;
        seconds = (elapsed / 1000) % 60;
        tenths = (elapsed / 100) % 10;
        snprintf(content, sizeof(content), "%02lu:%02lu.%lu\n\n%s",
                 (unsigned long)minutes, (unsigned long)seconds,
                 (unsigned long)tenths,
                 display->stopwatch_running ? "RUNNING" : "PAUSED");
        break;

      case VELAWEAR_APP_TASKS:
        snprintf(content, sizeof(content),
                 "[x] Audio initialization\n[x] Speaker test\n[ ] Microphone test\n[ ] Music playback\n[ ] Power tuning");
        break;

      case VELAWEAR_APP_DIAGNOSTICS:
        snprintf(content, sizeof(content),
                 "Uptime     %lu s\nFree RAM   %lu B\nPower mode %d\nTouch      ready\nAudio      tap to test",
                 (unsigned long)state->uptime_seconds,
                 (unsigned long)state->free_memory, state->power_mode);
        break;

      case VELAWEAR_APP_SETTINGS:
        snprintf(content, sizeof(content),
                 "OLED dark theme\nDisplay       ready\nAudio volume  70%%\nSleep         10/30/60 s\nKEY2          short/back, long/home");
        break;

      case VELAWEAR_APP_ABOUT:
        snprintf(content, sizeof(content),
                 "VelaWear Agent\nSF32LB52 Huangshan Pi\nFirmware %d.%d.%d\nLVGL display\nBuild target: lckfb_huangshan_pi",
                 VELAWEAR_VERSION_MAJOR, VELAWEAR_VERSION_MINOR,
                 VELAWEAR_VERSION_PATCH);
        break;

      default:
        snprintf(content, sizeof(content), "Unavailable");
        break;
    }

  lv_label_set_text(display->metrics_label, content);
}

static void display_build_app(velawear_display_t *display,
                              velawear_display_app_t app)
{
  lv_obj_t *summary;

  lv_obj_clean(display->detail_content);
  display->metrics_label = display_label(display->detail_content, "", UI_TEXT_COLOR);
  lv_obj_set_style_text_align(display->metrics_label, LV_TEXT_ALIGN_CENTER, 0);
  summary = display->metrics_label;
  (void)summary;

  switch (app)
    {
      case VELAWEAR_APP_AUDIO:
        display_action_button(display, "Test Speaker", DISPLAY_ACTION_AUDIO_SPEAKER);
        display_action_button(display, "Test Microphone", DISPLAY_ACTION_AUDIO_MIC);
        break;

      case VELAWEAR_APP_MUSIC:
        display_action_button(display, "Play / Pause", DISPLAY_ACTION_MUSIC_PLAY);
        break;

      case VELAWEAR_APP_STOPWATCH:
        display_action_button(display, "Start / Pause", DISPLAY_ACTION_STOP_START);
        display_action_button(display, "Reset", DISPLAY_ACTION_STOP_RESET);
        break;

      default:
        break;
    }
}

static void display_render_top(velawear_display_t *display,
                               const velawear_state_t *state)
{
  char content[256];
  char hint[48];
  time_t now;
  struct tm tm_now;
  const char *ble;

  if (display == NULL || state == NULL || display->detail_active)
    {
      return;
    }

  ble = state->ble_connected ? "ON" : "OFF";
  memset(&tm_now, 0, sizeof(tm_now));
  now = time(NULL);
  localtime_r(&now, &tm_now);

  if (display->page_index == VELAWEAR_PAGE_WATCHFACE)
    {
      snprintf(content, sizeof(content),
               "%02d:%02d\n\n%04d-%02d-%02d\n\nBattery %lu%%   BLE %s\n\nAudio Center  >",
               tm_now.tm_hour, tm_now.tm_min,
               tm_now.tm_year + 1900, tm_now.tm_mon + 1, tm_now.tm_mday,
               (unsigned long)state->battery_level, ble);
      lv_label_set_text(display->page_title, "VelaWear");
      lv_label_set_text(display->page_content[0], content);
      display->metrics_label = display->page_content[0];
      snprintf(hint, sizeof(hint), "Swipe left: Apps  |  1/2");
      lv_label_set_text(display->page_hint, hint);
    }
  else
    {
      lv_label_set_text(display->page_title, "Apps");
      snprintf(hint, sizeof(hint), "Tap an app  |  2/2");
      lv_label_set_text(display->page_hint, hint);
    }

  lv_label_set_text(display->status_label, "AGENT  |  READY");
  display_update_nav_dots(display);
}

