## Watchdog Timer

```c
// Configure independent watchdog (IWDG)
void Watchdog_Init(void) {
    // Enable write access to IWDG registers
    IWDG->KR = 0x5555;

    // Set prescaler to 64 (40kHz / 64 = 625Hz)
    IWDG->PR = IWDG_PR_PR_2;

    // Set reload value (625Hz / 625 = 1s timeout)
    IWDG->RLR = 625;

    // Reload counter
    IWDG->KR = 0xAAAA;

    // Start watchdog
    IWDG->KR = 0xCCCC;
}

// Reset watchdog
void Watchdog_Refresh(void) {
    IWDG->KR = 0xAAAA;
}
```

## Low-Power Modes

```c
// Enter sleep mode (CPU stopped, peripherals running)
void Enter_Sleep(void) {
    __WFI();  // Wait for interrupt
}

// Enter stop mode (all clocks stopped except LSI/LSE)
void Enter_Stop(void) {
    // Clear wakeup flags
    PWR->CR |= PWR_CR_CWUF;

    // Set SLEEPDEEP bit
    SCB->SCR |= SCB_SCR_SLEEPDEEP_Msk;

    // Enter stop mode
    PWR->CR &= ~PWR_CR_PDDS;
    PWR->CR |= PWR_CR_LPDS;

    __WFI();

    // Reconfigure clocks after wakeup
    SystemClock_Config();
}

// Enter standby mode (lowest power, RAM lost)
void Enter_Standby(void) {
    // Enable wakeup pin
    PWR->CSR |= PWR_CSR_EWUP;

    // Clear wakeup flags
    PWR->CR |= PWR_CR_CWUF;

    // Set SLEEPDEEP bit
    SCB->SCR |= SCB_SCR_SLEEPDEEP_Msk;

    // Enter standby mode
    PWR->CR |= PWR_CR_PDDS;

    __WFI();
}
```

