        pool = &dma2_ch_pool[0];
        ch_num = DMA2_CHANNEL_NUM;
        irq_type = DMAC2_CH1_IRQn;
    }
#else
    else if (0)
    {

    }
#endif /* DMA2 */
#ifdef DMA3
    else if (hdma->DmaBaseAddress == DMA3)
    {
        pool = &dma3_ch_pool[0];
        ch_num = DMA3_CHANNEL_NUM;
        irq_type = DMAC3_CH1_IRQn;
    }
#endif /* DMA3 */
    else
    {
        HAL_ASSERT(0);
    }

    index = hdma->ChannelIndex >> 2;
    HAL_ASSERT(index < ch_num);
    irq_type += index;
